// Splits file content into overlapping chunks suitable for embedding + retrieval.
// Simple line-based chunker: groups ~40 lines per chunk with 5 lines of overlap,
// which keeps most function/class bodies intact for typical source files.
export function chunkFile(content, { linesPerChunk = 40, overlap = 5 } = {}) {
  const lines = content.split("\n");
  const chunks = [];
  let start = 0;

  while (start < lines.length) {
    const end = Math.min(start + linesPerChunk, lines.length);
    const chunkText = lines.slice(start, end).join("\n").trim();
    if (chunkText.length > 0) chunks.push(chunkText);
    if (end === lines.length) break;
    start = end - overlap;
  }

  return chunks;
}

// Extensions worth indexing. Binary/lock/build files are skipped.
const INDEXABLE_EXTENSIONS = [
  ".js", ".jsx", ".ts", ".tsx", ".py", ".java", ".go", ".rb", ".php",
  ".c", ".cpp", ".h", ".hpp", ".cs", ".rs", ".md", ".json", ".yml", ".yaml",
  ".html", ".css", ".sql", ".env.example",
];

const EXCLUDED_PATH_PARTS = ["node_modules", ".git", "dist", "build", "coverage", "package-lock.json"];

export function isIndexable(filePath) {
  if (EXCLUDED_PATH_PARTS.some((part) => filePath.includes(part))) return false;
  return INDEXABLE_EXTENSIONS.some((ext) => filePath.endsWith(ext));
}

import axios from "axios";
import { isIndexable } from "./chunker.js";

// Parses a GitHub URL like https://github.com/owner/repo into { owner, repo }.
export function parseGithubUrl(url) {
  const match = url.match(/github\.com\/([^/]+)\/([^/]+?)(\.git)?\/?$/);
  if (!match) throw new Error("Invalid GitHub repository URL");
  return { owner: match[1], repo: match[2] };
}

function ghHeaders() {
  const headers = { Accept: "application/vnd.github+json" };
  if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  return headers;
}

// Fetches the full recursive file tree for a repo's default branch, then
// downloads content only for indexable text files (skips binaries, node_modules, etc).
export async function fetchRepoFiles(owner, repo) {
  const repoInfoRes = await axios.get(`https://api.github.com/repos/${owner}/${repo}`, {
    headers: ghHeaders(),
  });
  const defaultBranch = repoInfoRes.data.default_branch;

  const treeRes = await axios.get(
    `https://api.github.com/repos/${owner}/${repo}/git/trees/${defaultBranch}?recursive=1`,
    { headers: ghHeaders() }
  );

  const indexableFiles = treeRes.data.tree.filter(
    (item) => item.type === "blob" && isIndexable(item.path)
  );

  const files = [];
  for (const file of indexableFiles) {
    try {
      const blobRes = await axios.get(
        `https://api.github.com/repos/${owner}/${repo}/contents/${file.path}?ref=${defaultBranch}`,
        { headers: ghHeaders() }
      );

try {
      const blobRes = await axios.get(
        `https://api.github.com/repos/${owner}/${repo}/contents/${file.path}?ref=${defaultBranch}`,
        { headers: ghHeaders() }
      );
      const content = Buffer.from(blobRes.data.content, "base64").toString("utf-8");
      files.push({ path: file.path, content });
    } catch {
      // Skip files that fail to fetch (e.g. too large, LFS pointers)
      continue;
    }
  }

  return files;
}

